export const districts=[{name:'Harbour Works',desc:'Silent factories line the shore. Give this district a new purpose.',x:-4,z:-3},{name:'Old Town',desc:'Empty streets can become a place where neighbours meet again.',x:0,z:-3},{name:'East Bank',desc:'The water is rising. Nature could be your strongest defence.',x:4,z:-3},{name:'South Quarter',desc:'Families need homes, but a healthy city needs room to breathe.',x:-4,z:2},{name:'Foundry Hill',desc:'An industrial past. The energy for a cleaner tomorrow.',x:0,z:2},{name:'Sunset Point',desc:'What should children inherit at the edge of the world?',x:4,z:2}];
export const projects=[{id:'forest',name:'Urban forest',cost:28,effect:[18,2,6,12],hint:'+18 nature · +12 resilience',color:0x73bc76},{id:'solar',name:'Solar commons',cost:38,effect:[4,24,3,7],hint:'+24 energy · +7 resilience',color:0x4599cf},{id:'homes',name:'Living neighbourhood',cost:36,effect:[5,-5,24,4],hint:'+24 wellbeing · −5 energy',color:0xe5c9a0},{id:'wetland',name:'Coastal wetland',cost:30,effect:[14,0,4,24],hint:'+24 resilience · +14 nature',color:0x59bda9}];
export const neighbours=[[1,3],[0,2,4],[1,5],[0,4],[1,3,5],[2,4]];
export function placementBonus(s,index,id){const e=[0,0,0,0];if(id==='wetland'&&[0,2,5].includes(index))e[3]+=6;if(id==='solar'&&index===4)e[1]+=6;for(const n of neighbours[index])if((id==='forest'&&s.plots[n]==='homes')||(id==='homes'&&s.plots[n]==='forest'))e[2]+=4;return e;}
export function initial(){return {year:2050,budget:120,stats:[20,25,35,20],plots:Array(6).fill(null),history:[],log:['2050 · You inherit a city that has forgotten how to breathe.'],ended:false};}
export function score(s){return Math.round(s.stats.reduce((a,b)=>a+b,0)/4);}
export function isWin(s){return s.ended&&score(s)>=70&&s.plots.every(Boolean)&&s.stats.every(n=>n>=50);}
export function build(s,index,id){if(s.ended)throw Error('This city’s story is complete. Start a new city to play again.');if(!Number.isInteger(index)||index<0||index>5)throw Error('Choose a district from 1 to 6.');const p=projects.find(p=>p.id===id);if(!p)throw Error('Unknown restoration project.');if(s.plots[index])throw Error('This district is already restored.');if(s.budget<p.cost)throw Error('Not enough credits. Advance a year to earn 24.');const bonus=placementBonus(s,index,id);s.budget-=p.cost;s.plots[index]=id;s.history.push([s.year,index,['forest','solar','homes','wetland'].indexOf(id)]);s.stats=s.stats.map((n,i)=>Math.max(0,Math.min(100,n+p.effect[i]+bonus[i])));s.log.unshift(`${s.year} · ${districts[index].name}: ${p.name} opens.`);return s;}
export function advance(s){if(s.ended)throw Error('This city’s story is complete.');s.year++;s.budget+=24;let event='A new year. Community funding adds 24 credits.';if(s.year===2053){const loss=s.stats[3]<55?14:3;s.stats[2]=Math.max(0,s.stats[2]-loss);event=`A coastal storm arrives. ${loss===3?'Your resilient coastline protects the city.':'The unprotected coast takes damage.'} Wellbeing −${loss}.`;}if(s.year===2056){const loss=s.stats[0]<55?12:2;s.stats[2]=Math.max(0,s.stats[2]-loss);event=`A heatwave tests the city. ${loss===2?'Green space keeps the streets cool.':'Too little shade leaves families exposed.'} Wellbeing −${loss}.`;}s.log.unshift(`${s.year} · ${event}`);s.ended=s.year>=2058;return s;}
